// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    address initializer;

    function setUp() public {
        c = new RoundFactory();
        initializer = address(0xA11CE);
        vm.prank(initializer);
        c.initialize();
    }

    function testFuzz_property(address newOwner, address nextTarget) public {
        // wide admissible domain: any address, including address(0), any follow-up target
        // caller is the current owner, so only the zero-address rule can gate the call
        bool ok;
        vm.prank(initializer);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // GENERAL RULE: a successful transfer makes newOwner the owner, and that
            // owner is a live, non-zero address from which ownership remains transferrable.
            // The mutant accepts newOwner == address(0): owner() becomes address(0),
            // violating this rule for the fuzzer-discoverable input newOwner == 0.
            assertTrue(c.owner() == newOwner && newOwner != address(0));
        } else {
            // reference may only reject when the target is the zero address
            assertTrue(newOwner == address(0));
        }
    }
}
